        var obj = typeof raw === 'string' ? JSON.parse(raw) : (raw || []);
        var list = Array.isArray(obj) ? obj : (obj.comments || obj.items || []);
        list.forEach(function (c) {
            var body = String((c && c.body) || '');
            var m;
            RED_HEAD_MARKER_RE.lastIndex = 0;
            while ((m = RED_HEAD_MARKER_RE.exec(body)) !== null) {
                var n = parseInt(m[2], 10) || 0;
                if (!out[m[1]] || n > out[m[1]]) out[m[1]] = n;
            }
        });
    } catch (eHist) {
        // Fail OPEN (arm): an unreadable history costs at most one more
        // validation run; a wrongful skip would park a healthy PR.
        console.warn('  ⚠️  red-head history read failed: ' + (eHist.message || eHist));
    }
    return out;
}

// Is THIS head red-blocked (>= cap recorded reds on the same SHA)?
function redHeadBlocked(repoInfo, prNumber, headSha, cap) {
    if (!headSha) return false;
    var hist = redHeadHistory(repoInfo, prNumber);
    return (hist[headSha] || 0) >= cap;
}

// The marker line the NEXT fail report appends for this head: counts the
// prior markers on the same SHA (N = prior + 1), cap noted for the reader.
// null when the head SHA is unknown — nothing to record.
function redHeadMarkerLine(repoInfo, prNumber, headSha, cap) {
    if (!headSha) return null;
    var prior = (redHeadHistory(repoInfo, prNumber)[headSha] || 0);
    return '\uD83D\uDD34 red head ' + headSha + ' \u2014 red ' + (prior + 1) + '/' + cap +
        ' (owner directive 2026-10-04: red yields the slot \u2014 after ' + cap +
        ' reds on the same head, validation waits for a NEW head)';
