function hasActiveDispatchedRun(repoInfo, ciWorkflow, headSha) {
    try {
        var res = cli_execute_command({
            command: 'gh api "repos/' + repoInfo.owner + '/' +
                     repoInfo.repo +
                     '/actions/workflows/' + ciWorkflow +
                     '/runs?head_sha=' + headSha +
